/* Pixel Interval Trainer – styles */
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --primary-hover: #ff6b81;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --accent: #0f3460;
  --focus: #ffd369;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 24px;
  color: var(--primary);
  letter-spacing: 0.5px;
}

.settings {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  text-align: left;
}

label {
  font-size: 1rem;
  color: var(--text-muted);
  font-weight: 500;
}

input[type="number"] {
  font-size: 1.25rem;
  padding: 10px 12px;
  border: 2px solid var(--accent);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  width: 100%;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input[type="number"]:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(255, 211, 105, 0.25);
}

button {
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  width: 100%;
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.primary {
  background: var(--primary);
  color: #fff;
}

.primary:hover {
  background: var(--primary-hover);
}

.primary:active {
  transform: scale(0.98);
  background: #c7354c;
}

.secondary {
  background: var(--accent);
  color: var(--text);
  margin-top: 16px;
}

.secondary:hover {
  background: #1a4a7a;
}

.secondary:active {
  transform: scale(0.98);
  background: #0a2a4a;
}

.timer {
  background: var(--bg);
  border-radius: 12px;
  padding: 24px 16px;
  margin-bottom: 16px;
}

.phase {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--primary);
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.time {
  font-size: 3.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
  margin-bottom: 8px;
}

.round {
  font-size: 1rem;
  color: var(--text-muted);
}

.status {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--focus);
  min-height: 1.5em;
}

/* Utility */
[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .time {
    font-size: 2.75rem;
  }
}

// Pixel Interval Trainer – logic
(function () {
  'use strict';

  const form = document.getElementById('settings-form');
  const workInput = document.getElementById('work-seconds');
  const restInput = document.getElementById('rest-seconds');
  const roundsInput = document.getElementById('rounds');
  const startBtn = document.getElementById('start-btn');
  const stopBtn = document.getElementById('stop-btn');
  const phaseLabel = document.getElementById('phase-label');
  const timeLeftEl = document.getElementById('time-left');
  const roundLabel = document.getElementById('round-label');
  const statusMessage = document.getElementById('status-message');

  let timerId = null;
  let state = null; // { phase, timeLeft, currentRound, totalRounds, workSec, restSec }

  function clearTimer() {
    if (timerId !== null) {
      clearInterval(timerId);
      timerId = null;
    }
  }

  function updateDisplay() {
    if (!state) {
      phaseLabel.textContent = 'Ready';
      timeLeftEl.textContent = '--';
      roundLabel.textContent = 'Round 0 / 0';
      return;
    }
    phaseLabel.textContent = state.phase === 'work' ? 'Work' : 'Rest';
    timeLeftEl.textContent = state.timeLeft + 's';
    roundLabel.textContent = 'Round ' + state.currentRound + ' / ' + state.totalRounds;
  }

  function finishWorkout() {
    clearTimer();
    state = null;
    phaseLabel.textContent = 'Done';
    timeLeftEl.textContent = '0s';
    roundLabel.textContent = 'Workout complete';
    statusMessage.textContent = 'Workout complete';
    startBtn.hidden = false;
    stopBtn.hidden = true;
  }

  function tick() {
    if (!state) return;

    if (state.timeLeft > 0) {
      state.timeLeft--;
      updateDisplay();
      return;
    }

    // Phase transition
    if (state.phase === 'work') {
      state.phase = 'rest';
      state.timeLeft = state.restSec;
      updateDisplay();
    } else {
      // End of rest → next round or finish
      if (state.currentRound >= state.totalRounds) {
        finishWorkout();
      } else {
        state.currentRound++;
        state.phase = 'work';
        state.timeLeft = state.workSec;
        updateDisplay();
      }
    }
  }

  function startWorkout(e) {
    if (e) e.preventDefault();

    const workSec = parseInt(workInput.value, 10);
    const restSec = parseInt(restInput.value, 10);
    const totalRounds = parseInt(roundsInput.value, 10);

    if (!workSec || !restSec || !totalRounds || workSec < 1 || restSec < 1 || totalRounds < 1) {
      statusMessage.textContent = 'Please enter valid positive numbers.';
      return;
    }

    clearTimer();
    statusMessage.textContent = '';

    state = {
      phase: 'work',
      timeLeft: workSec,
      currentRound: 1,
      totalRounds: totalRounds,
      workSec: workSec,
      restSec: restSec
    };

    updateDisplay();
    startBtn.hidden = true;
    stopBtn.hidden = false;

    timerId = setInterval(tick, 1000);
  }

  function stopWorkout() {
    clearTimer();
    state = null;
    updateDisplay();
    statusMessage.textContent = 'Stopped.';
    startBtn.hidden = false;
    stopBtn.hidden = true;
  }

  form.addEventListener('submit', startWorkout);
  stopBtn.addEventListener('click', stopWorkout);

  // Initial display
  updateDisplay();
})();
